pseudocode.ordinary:
offset = beacon - body.position
distance = length(offset)

acceleration = sceneEngine.seek(body, beacon)
// seek returns normalise(offset) * body.maxAcceleration
// normalise of a zero vector is a zero vector

trialVelocity = body.velocity + acceleration * timeStep
velocity = clipLength(trialVelocity, body.maxSpeed)

position = body.position + velocity * timeStep
body = body with { position, velocity }
// Repeat from the new state; there is no arrival condition.
